<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {RouterLink,useRoute} from 'vue-router';
import {api,ApiError} from '../lib/api';
import {usePageTitle} from '../lib/page-title';
import {prepareNpcPortrait} from '../lib/npc-portrait';
import PortraitZoom from '../components/PortraitZoom.vue';
import CampaignLiveSessions from '../components/CampaignLiveSessions.vue';
import CampaignRewards from '../components/CampaignRewards.vue';
import CampaignEffects from '../components/CampaignEffects.vue';
import CampaignCombat from '../components/CampaignCombat.vue';
import CampaignCharacterPlay from '../components/CampaignCharacterPlay.vue';
import CampaignNpcPreview from '../components/CampaignNpcPreview.vue';
import CampaignCreaturePreview from '../components/CampaignCreaturePreview.vue';
const route=useRoute(),id=String(route.params.id),endpoint=`/api/campaigns/${id}/play`;
const room=ref<any>(null),error=ref(''),actionError=ref(''),busy=ref(false),notice=ref(''),selected=ref(typeof route.query.actor==='string'?route.query.actor:''),filter=ref('all');
const feedCollapsed=ref(false),edgeRequest=ref<any>(null);
async function forceFeed(eventId:string){if(busy.value||!room.value?.ownCharacterId)return;busy.value=true;actionError.value='';try{const path=`/api/characters/${room.value.ownCharacterId}/play`;if(!edgeRequest.value){const p=await api<any>(path);edgeRequest.value={requestId:crypto.randomUUID(),version:p.version,action:'edge-force',eventId};}await api(path,{method:'POST',body:JSON.stringify(edgeRequest.value)});edgeRequest.value=null;await load();}catch(e){actionError.value=e instanceof ApiError&&e.message==='insufficient_edge'?'Tu n’as plus d’Edge.':e instanceof ApiError&&e.message==='edge_roll_resolved'?'Ce jet est déjà résolu.':'Dépense non confirmée. Réessaie le même jet.';if(e instanceof ApiError&&e.status<500)edgeRequest.value=null;}finally{busy.value=false;}}
async function rollOwnInitiative(){if(busy.value||!room.value?.ownCharacterId)return;busy.value=true;actionError.value='';try{const path=`/api/characters/${room.value.ownCharacterId}/play`,p=await api<any>(path);await api(path,{method:'POST',body:JSON.stringify({requestId:crypto.randomUUID(),version:p.version,action:'initiative'})});await load();}catch(e){actionError.value=e instanceof ApiError&&e.message==='initiative_already_rolled'?'Ton initiative est déjà lancée.':'Initiative non confirmée : actualise avant de réessayer.';}finally{busy.value=false;}}
const ownActor=computed(()=>room.value?.characters.find((c:any)=>c.id===room.value?.ownCharacterId));
const sideLabel=(side:string)=>({ally:'Allié',enemy:'Ennemi',neutral:'Neutre'}[side]??'Neutre');
const availableRolls=computed(()=>chosen.value?.rolls?.filter((r:any)=>room.value?.combat?.active||!r.attack&&!r.requiresWeapon&&!r.defense)??[]);
const latest=computed(()=>room.value?.events?.find((e:any)=>e.payload.dice));
const passOf=(actorId:string)=>room.value?.passes?.find((p:any)=>p.id===actorId)?.pass??null;
function passHeading(index:number){if(!room.value?.combat?.active)return '';const pass=passOf(roster.value[index].id);if(index&&pass===passOf(roster.value[index-1].id))return '';return pass===null?'Sans action disponible':`Passe ${pass}`;}
const text=ref(''),link=ref(''),image=ref(''),imageBusy=ref(false);
const sourceCatalog=ref('compendium'),globalSources=ref<any[]>([]);
const sourceKind=ref('npc'),sourceQuery=ref(''),sources=ref<any[]>([]),sourceId=ref(''),sourceName=ref(''),hasMore=ref(false),sourceLoading=ref(false);
const graceHp=ref(1),graceReason=ref('Annulation d’une mort pendant un test');
const actorName=ref(''),actorPa=ref(0),actorVisible=ref(false),actorDirty=ref(false),amount=ref(1);
const gmMode=ref('explosive'),gmFaces=ref(20),gmCount=ref(1);
const gmLabel=ref('Jet libre'),gmBonus=ref(0),gmStress=ref(0),gmPublic=ref(true);
const combatPanel=ref<InstanceType<typeof CampaignCombat>|null>(null);
function participantRoll(){if(rollOption.value?.attack||rollOption.value?.requiresWeapon){void combatPanel.value?.prepareAttack(chosen.value.id,rollId.value);return;}actorAction('roll',{rollId:rollId.value,label:rollLabel.value,bonus:rollBonus.value,stress:rollStress.value,public:rollPublic.value,paCost:room.value?.combat?.active?rollPa.value:0});}
const rollId=ref(''),rollBonus=ref(0),rollStress=ref(0),rollPublic=ref(true),rollPa=ref(0),rollLabel=ref('');
const pending=ref<any>(null);let alive=true,loading=false,timer:ReturnType<typeof setInterval>|undefined,sourceGeneration=0;
usePageTitle(()=>room.value?`${room.value.campaignName} — En jeu`:'En jeu · Campagne');
const roster=computed(()=>{const all=[...(room.value?.characters??[]),...(room.value?.combatants??[])];const ranks=new Map((room.value?.order??[]).map((key:string,i:number)=>[key,i]));return all.sort((a,b)=>Number(ranks.get(a.id)??999)-Number(ranks.get(b.id)??999));});
const chosen=computed(()=>roster.value.find(c=>c.id===selected.value));
watch(availableRolls,rows=>{if(!rows.some((r:any)=>r.id===rollId.value))rollId.value=rows[0]?.id??'';});
const rollOption=computed(()=>chosen.value?.rolls?.find((r:any)=>r.id===rollId.value));
watch(()=>chosen.value?.id,()=>{rollId.value=chosen.value?.rolls?.[0]?.id??'';rollBonus.value=0;rollStress.value=0;});
watch(rollOption,(r,old)=>{if(r?.id!==old?.id){rollLabel.value=r?.label??'';rollPa.value=r?.attack?1:0;}});
const feed=computed(()=>(room.value?.events??[]).filter((e:any)=>filter.value==='all'||(filter.value==='rolls'?Array.isArray(e.payload.dice):e.kind==='message')));
async function load(){if(!alive||loading||document.visibilityState==='hidden')return;loading=true;try{const r=await api<any>(endpoint);if(!alive)return;room.value=r;error.value='';if(!selected.value)selected.value=r.ownCharacterId??'';if(selected.value&&!roster.value.some(c=>c.id===selected.value))selected.value=r.ownCharacterId??'';}catch{if(alive){room.value=null;error.value='La campagne est inaccessible. Vérifie ta connexion et ton invitation.';}}finally{loading=false;}}
watch(()=>({id:chosen.value?.id,version:chosen.value?.version}),(next,previous)=>{if(next.id!==previous?.id)actorDirty.value=false;if(chosen.value&&!actorDirty.value){actorName.value=chosen.value.name;actorPa.value=chosen.value.pa??0;actorVisible.value=chosen.value.visible??false;}});
async function act(action:string,extra:Record<string,unknown>={}){
 if(busy.value||!room.value?.canManage&&action!=='spend')return;
 if(pending.value){actionError.value='Réessaie l’action non confirmée avant une autre modification.';return;}
 pending.value={requestId:crypto.randomUUID(),action,...extra};await sendPending();
}
async function sendPending(){if(busy.value||!pending.value)return;busy.value=true;actionError.value='';notice.value='';try{const action=pending.value.action;await api(['spend','grace'].includes(action)?`/api/campaigns/${id}/combat`:endpoint+'/actions',{method:'POST',body:JSON.stringify(pending.value)});pending.value=null;if(!alive)return;if(action==='message'){text.value='';link.value='';image.value='';}actorDirty.value=false;notice.value='Enregistré.';await load();}catch(e){if(alive){actionError.value=e instanceof ApiError&&e.status===409?'Une autre fenêtre a modifié cet état. Les valeurs ont été actualisées.':e instanceof ApiError&&e.message==='finish_combat_first'?'Termine le combat et résous les attaques en attente avant de changer de scène ou de scénario.':e instanceof ApiError&&e.message==='pending_attacks'?'Résous ou annule les attaques en attente avant de changer de round ou de terminer le combat.':e instanceof ApiError&&e.message==='campaign_combat_mj_only'?'Le MJ contrôle les rounds du groupe.':e instanceof ApiError&&e.message==='initiatives_pending'?'Il reste des initiatives à lancer. Lance-les ou sors les participants absents des tours.':e instanceof ApiError&&e.message==='participant_out'?'Ce participant est hors des tours. Le MJ peut le réintégrer.':e instanceof ApiError&&e.message==='combat_not_started'?'Lance l’initiative de ce participant pour commencer son combat.':e instanceof ApiError&&e.message==='insufficient_pa'?'Ce participant n’a pas assez de PA.':e instanceof ApiError&&['character_dead','character_agonizing'].includes(e.message)?'L’état du participant empêche ce jet.':'La modification n’a pas été confirmée. Réessaie.';if(e instanceof ApiError&&e.status<500){pending.value=null;actorDirty.value=false;await load();}}}finally{busy.value=false;}}
function actorAction(action:string,extra:Record<string,unknown>={}){if(chosen.value)void act(action,{combatantId:chosen.value.id,version:chosen.value.version,...extra});}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;imageBusy.value=true;try{image.value=await prepareNpcPortrait(file,1600);actionError.value='';}catch(e){actionError.value=e instanceof Error?e.message:'Image illisible.';}finally{imageBusy.value=false;input.value='';}}
async function findSources(more=false){if(sourceLoading.value)return;const generation=++sourceGeneration;sourceLoading.value=true;try{if(sourceCatalog.value==='compendium'){if(!globalSources.value.length){const r=await api<any>(endpoint+'/catalog');globalSources.value=r.entries;}if(!alive||generation!==sourceGeneration)return;sources.value=globalSources.value.filter(s=>s.kind===sourceKind.value&&s.name.toLocaleLowerCase().includes(sourceQuery.value.toLocaleLowerCase()));hasMore.value=false;sourceId.value='';sourceName.value='';return;}const kind=sourceKind.value,r=await api<any>(`/api/campaigns/${id}/${kind==='npc'?'npcs':'bestiary'}?q=${encodeURIComponent(sourceQuery.value)}&offset=${more?sources.value.length:0}`);if(!alive||generation!==sourceGeneration)return;sources.value=more?[...sources.value,...(r.npcs??r.creatures)]:r.npcs??r.creatures;hasMore.value=r.hasMore;if(!more){sourceId.value='';sourceName.value='';}}catch{actionError.value='Impossible de charger le catalogue de la campagne.';}finally{sourceLoading.value=false;if(alive&&generation!==sourceGeneration)void findSources();}}
watch([sourceKind,sourceCatalog],()=>{++sourceGeneration;sources.value=[];sourceId.value='';sourceName.value='';hasMore.value=false;void findSources();});
watch(sourceId,()=>{sourceName.value=sources.value.find(s=>s.id===sourceId.value)?.name??'';});
const date=(v:string)=>new Date(v).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
function focus(){void load();}
onMounted(()=>{void load();timer=setInterval(()=>void load(),3000);window.addEventListener('focus',focus);document.addEventListener('visibilitychange',focus);});
onUnmounted(()=>{alive=false;++sourceGeneration;clearInterval(timer);window.removeEventListener('focus',focus);document.removeEventListener('visibilitychange',focus);});
</script>
<template>
 <div class="live-page"><header class="live-header"><div><p class="eyebrow">TERRA UMBRA · EN JEU</p><h1>{{ room?.campaignName??'Table de jeu' }}</h1></div><nav><RouterLink :to="`/campaigns/${id}`">← Campagne</RouterLink><RouterLink to="/account">Mon espace</RouterLink></nav></header>
 <div v-if="error" role="alert"><p>{{ error }}</p><RouterLink :to="`/account?redirect=${encodeURIComponent(route.fullPath)}`">Se connecter</RouterLink><button @click="load">Réessayer</button></div>
 <p v-else-if="!room" role="status">Ouverture de la table…</p>
 <div v-else class="live-layout">
  <aside class="initiative-rail" aria-label="Participants par initiative"><h2>Participants</h2><p>{{ room.combat?.active?`Round ${room.combat.round} · ordre par passe`:'Personnages présents à la table' }}</p>
   <ol><template v-for="(c,index) in roster" :key="c.id"><li v-if="passHeading(index)" class="pass-divider" role="separator">{{ passHeading(index) }}</li><li :class="[{selected:c.id===selected,hiddenActor:c.visible===false,outOfTurns:c.participating===false},`side-${c.side??'neutral'}`]"><PortraitZoom v-if="c.portrait" :src="c.portrait" :name="c.name" /><div><strong>{{ c.name }}</strong><small>{{ c.kind==='character'?[c.occupation,c.sphere].filter(Boolean).join(' · '):c.kind==='npc'?'PNJ':'Créature' }}</small><span class="health">{{ c.health }}</span><small>{{sideLabel(c.side)}} · {{c.participating===false?'Hors des tours':room.combat?.active&&c.initiativePending?'Initiative à lancer':'Présent'}}</small><small v-if="c.visible===false">Caché aux joueurs</small><small v-if="c.hp!==undefined&&room.combat?.active">{{ c.hp }} / {{ c.pvMax }} PV · {{ c.pa }} PA</small><small v-if="room.combat?.active&&c.initiative!=null">Initiative {{ c.initiative }}</small></div><div class="rail-actions" v-if="room.canManage||c.id===room.ownCharacterId"><button @click="selected=c.id">{{ c.id===selected?'Fiche ouverte':'Agrandir' }}</button><a :href="c.kind==='character'?`/characters/${c.id}/play?campaign=${id}`:`/campaigns/${id}/play?actor=${c.id}`" target="_blank" rel="noopener" :aria-label="`Ouvrir ${c.name} dans un nouvel onglet`">↗</a><button v-if="room.canManage&&room.combat?.active&&c.kind!=='character'&&c.initiativePending&&c.participating!==false" :disabled="busy" @click="act('initiative',{combatantId:c.id,version:c.version})">◈ Initiative</button><button v-if="room.combat?.active&&c.participating!==false&&c.pa>0" :disabled="busy" @click="act('spend',{actorId:c.id})">Action hors attaque · 1 PA</button></div></li></template></ol><p v-if="!roster.length">Aucun participant visible.</p>
   <details v-if="room.canManage" @toggle="($event.target as HTMLDetailsElement).open&&findSources()"><summary>Ajouter un PNJ ou une créature</summary><label>Source<select v-model="sourceCatalog"><option value="compendium">Compendium</option><option value="campaign">Cette campagne</option></select></label><label>Catalogue<select v-model="sourceKind"><option value="npc">PNJ</option><option value="creature">Bestiaire</option></select></label><form @submit.prevent="findSources()"><label>Filtrer la liste (facultatif)<input v-model="sourceQuery" maxlength="100" @input="sourceCatalog==='compendium'&&findSources()" /></label><button :disabled="sourceLoading">Rechercher dans le catalogue</button></form><p v-if="sourceLoading" role="status">Chargement du catalogue…</p><label>Fiche source<select v-model="sourceId" aria-label="Fiche source"><option value="">Choisir…</option><option v-for="s in sources" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><button v-if="hasMore" :disabled="sourceLoading" @click="findSources(true)">Afficher la suite</button><label>Nom affiché<input v-model="sourceName" maxlength="120" placeholder="Ex. Garde du portail" /></label><button :disabled="busy||!sourceId||!sourceName.trim()" @click="act('add',{catalog:sourceCatalog,kind:sourceKind,sourceId,name:sourceName,visible:false})">Ajouter à la table, caché</button><p>Révèle ensuite le participant depuis sa fiche. Tu peux ajouter plusieurs exemplaires d’une créature.</p></details>
  </aside>
  <main class="live-main"><div class="mode-heading" role="status"><h2>{{room.combat?.active?'Combat · Round '+room.combat.round:'Exploration & vie du personnage'}}</h2><p>{{room.combat?.active?'Initiative → arme et cible → action → défense et dégâts':'Jets courants, équipement, modificateurs et capacités'}}</p></div>   <details v-if="room.canManage" class="combat-controls" open><summary>Combat · {{ room.combat?.active?'Round '+room.combat.round:'hors combat' }}</summary><div class="actor-controls"><label>Passage des rounds<select :value="room.combat?.mode??'manual'" :disabled="busy" @change="act('combat-mode',{version:room.combat?.version??0,mode:($event.target as HTMLSelectElement).value})"><option value="manual">Manuel · le MJ décide</option><option value="automatic">Automatique · plus aucun PA visible</option></select></label><button v-if="!room.combat?.active" :disabled="busy" @click="act('combat-start',{version:room.combat?.version??0})">Lancer le combat</button><template v-else><button :disabled="busy" @click="act('combat-round',{version:room.combat.version})">Round suivant pour tous</button><button :disabled="busy" @click="act('combat-stop',{version:room.combat.version})">Arrêter le combat</button></template></div><p>Chaque joueur lance son initiative une fois ; le MJ lance celles des PNJ et créatures. Un participant en attente d’initiative bloque le round suivant. Les participants hors des tours ne le bloquent pas. En automatique, seuls les participants visibles encore en vie comptent ; les attaques en attente doivent être résolues. Une attaque dépense déjà son PA. Utilise « Action hors attaque » pour les autres actions.</p></details>
   <p v-else-if="room.combat?.active" class="round-status">Round {{room.combat.round}} · {{room.combat.mode==='automatic'?'passage automatique':'rounds dirigés par le MJ'}}</p>

   <details v-if="room.canManage&&!room.combat?.active" class="combat-controls"><summary>Scènes & usages des capacités · MJ</summary><p>Déclare une nouvelle scène ou un nouveau scénario lorsque la fiction le justifie. Une séance ou un combat ne renouvelle pas automatiquement les capacités. Les PV, l’Edge, l’inventaire et le compteur de Mues depuis le repos restent inchangés.</p><button :disabled="busy" @click="act('combat-scene',{version:room.combat.version})">Nouvelle scène · renouveler les usages de scène</button><button :disabled="busy" @click="act('combat-scenario',{version:room.combat.version})">Nouveau scénario · renouveler tous les usages</button></details>
   <CampaignLiveSessions v-show="!room.combat?.active" :campaign-id="id" :can-manage="room.canManage" :current="room.session" @changed="load" />
   <CampaignRewards v-if="room.canManage&&!room.combat?.active" :campaign-id="id" :can-manage="true" in-play @changed="load" />
   <div v-if="room.combat?.active&&ownActor?.initiativePending&&ownActor?.participating!==false" class="combat-controls"><strong>À toi : lance ton initiative pour ce combat.</strong> <button :disabled="busy" @click="rollOwnInitiative">◈ Lancer mon initiative</button><button @click="selected=room.ownCharacterId">Ma fiche / dépenser de l’Edge</button></div>
   <section class="live-feed" :class="{collapsed:feedCollapsed}"><header><h2>Jets & révélations</h2><button :aria-expanded="!feedCollapsed" aria-controls="table-feed-content" @click="feedCollapsed=!feedCollapsed">{{ feedCollapsed?'Déplier':'Replier' }}</button><label v-show="!feedCollapsed">Afficher<select v-model="filter"><option value="all">Tout le fil</option><option value="rolls">Jets de dés</option><option value="messages">Révélations du MJ</option></select></label></header>
    <p v-if="latest" class="latest-result" role="status" aria-live="polite">{{latest.characterName??latest.payload.characterName??'MJ'}} → {{latest.payload.label}} → <strong>{{latest.payload.total}}</strong><span v-if="latest.payload.narrativeFailure"> · Échec narratif</span><span v-else-if="latest.payload.edgeForced"> · Forcer le Destin</span><span v-else-if="latest.payload.exploded"> · Explosion !</span></p>
    <div id="table-feed-content" v-show="!feedCollapsed" class="feed-content"><div class="feed-scroll" role="log" aria-label="Journal des jets et révélations" tabindex="0"><article v-for="e in feed" :key="e.id" :class="['feed-event',{'reveal':e.kind==='message','failed':e.payload.narrativeFailure}]"><header><time>{{ date(e.createdAt) }}</time><strong>{{ e.characterName??e.payload.characterName??'MJ' }} → {{ e.payload.label }}<template v-if="e.payload.total!==undefined"> → {{ e.payload.total }}</template></strong></header><small v-if="e.playerName">{{ e.playerName }}</small>
     <p v-if="e.payload.selectedName"><strong>{{ e.payload.selectedName }}</strong> · parmi {{ e.payload.candidateCount }} joueurs</p><template v-if="e.payload.dice"><strong v-if="e.payload.edgeForced">Forcer le Destin · 1 Edge</strong><p class="dice-detail">{{ e.payload.modifier }} + <span v-for="(die,i) in e.payload.dice" :key="i">{{ i?' + ':'' }}<b>{{ die }}</b>{{ i&&e.payload.exploded?' (explosion)':'' }}</span> = <strong>{{ e.payload.total }}</strong></p><button v-if="room.ownCharacterId===(e.characterId??e.payload.characterId)&&!e.payload.edgeForced&&['roll','initiative','defend'].includes(e.kind)" :disabled="busy" @click="forceFeed(e.id)">Forcer ce jet · 1 Edge</button><strong v-if="e.payload.narrativeFailure" class="failure">Échec narratif</strong><details><summary>Détail du jet</summary><p v-if="e.payload.components?.attributeName">{{ e.payload.components.attributeName }} {{ e.payload.components.attribute }} + {{ e.payload.components.skillName }} {{ e.payload.components.rank }} + bonus {{ e.payload.components.bonus }}</p><p v-else-if="e.payload.components?.profileScore!==undefined">{{e.payload.components.profileName}} · score du profil {{e.payload.components.profileScore}} + bonus {{e.payload.components.bonus}}</p><p v-else-if="e.payload.components?.defense!==undefined">Défense {{e.payload.components.defense}} + bonus {{e.payload.components.bonus}} + {{e.payload.defensePowerName??'capacité'}} {{e.payload.components.specialBonus??0}} · {{e.payload.paCost??0}} PA</p><p v-else>Bonus du jet : {{ e.payload.modifier }}</p><p v-if="e.payload.weaponName">Arme / attaque : {{e.payload.weaponName}} · DGT {{e.payload.damage}}</p><p>Dés : {{e.payload.dice.join(' + ')}} · total {{e.payload.total}}</p><ul v-if="e.payload.bonuses?.length"><li v-for="(b,i) in e.payload.bonuses" :key="i">{{ b.label??b.name??b.id }} : {{ b.amount??b.bonus??0 }}</li></ul></details></template>
     <p v-if="e.kind==='resolve'">Attaque {{ e.payload.attackTotal }} contre défense {{ e.payload.defenseTotal }}<template v-if="e.payload.defenseDice?.length"> (dés : {{ e.payload.defenseDice.join(' + ') }})</template> · <strong>{{ e.payload.damage }} dégâts appliqués</strong></p><p v-if="e.kind==='resolve'&&e.payload.alteration">Altération cohérente à déterminer avec le MJ.</p><p v-if="e.kind!=='resolve'&&e.payload.damage!==undefined">Dégâts de base : {{ e.payload.damage }} · à résoudre selon la défense et l’armure.</p><p v-if="e.payload.text" class="message-text">{{ e.payload.text }}</p><a v-if="e.payload.link" :href="e.payload.link" target="_blank" rel="noopener">Ouvrir la page du Compendium ↗</a><a v-if="e.image" :href="e.image" target="_blank" rel="noopener"><img class="reveal-image" :src="e.image" alt="Image révélée par le MJ" loading="lazy" /></a><p v-if="e.payload.before!==undefined">{{ e.payload.before }} → {{ e.payload.after }} PV</p><p v-if="e.payload.reserveBonus">Réserve nanitique : +{{e.payload.reserveBonus}} PV inclus dans ce soin.</p><p v-if="e.payload.recovered!==undefined">+{{ e.payload.recovered }} PV récupérés</p><button v-if="room.canManage&&e.kind==='message'" :disabled="busy" @click="act('withdraw',{eventId:e.id})">Retirer cette révélation</button>
    </article><p v-if="!feed.length">Les prochains jets et révélations apparaîtront ici.</p></div>
    <details v-if="room.canManage" class="gm-roll"><summary>Jet libre du MJ</summary><form @submit.prevent="act(gmMode==='player'?'random-player':'gm-roll',{label:gmLabel,bonus:gmBonus,stress:gmStress,public:gmPublic,mode:gmMode,faces:gmFaces,count:gmCount})"><div class="actor-controls"><label>Type de tirage<select v-model="gmMode" aria-label="Type de tirage"><option value="explosive">d10 explosif · règles de jeu</option><option value="dice">Dés libres</option><option value="player">Un joueur au hasard</option></select></label><template v-if="gmMode==='dice'"><label>Nombre de dés<input v-model.number="gmCount" type="number" min="1" max="50" /></label><label>Faces par dé<input v-model.number="gmFaces" type="number" min="2" max="1000" list="gm-dice-faces" /><datalist id="gm-dice-faces"><option v-for="n in [4,6,8,10,12,20,100]" :key="n" :value="n" /></datalist></label></template><label>Intitulé du jet MJ<input v-model="gmLabel" maxlength="120" required /></label><label>Modificateur MJ<input v-model.number="gmBonus" type="number" min="-100" max="100" required /></label><label>Stress du jet MJ<select v-model.number="gmStress"><option :value="0">Neutre</option><option :value="1">Tendu</option><option :value="2">Paniqué</option></select></label><label class="check"><input v-model="gmPublic" type="checkbox" /> Jet MJ visible par les joueurs</label><button :disabled="busy||!gmLabel.trim()">{{ gmMode==='player'?'Tirer un joueur au hasard':'Lancer les dés · MJ' }}</button></div></form></details>
    <details v-if="room.canManage" class="compose"><summary>Révéler quelque chose au groupe</summary><form @submit.prevent="act('message',{text,link,image})"><label>Message ou information révélée<textarea v-model="text" maxlength="5000" rows="3" /></label><label>Lien vers une page du Compendium<input v-model="link" maxlength="1000" placeholder="https://terra-umbra.fr/compendium?article=…" /></label><small>Le lien conserve les droits de lecture de la page. Pour révéler une information réservée au MJ, partage ici le texte ou l’image choisis.</small><label>Image à révéler<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="imageBusy||busy" @change="upload" /></label><img v-if="image" :src="image" alt="Aperçu avant révélation" class="image-preview" /><button v-if="image" type="button" @click="image=''">Retirer l’image jointe</button><button :disabled="busy||imageBusy||(!text.trim()&&!link&&!image)">Révéler au groupe</button></form></details>
    </div>
   </section>
   <p v-if="actionError" role="alert">{{ actionError }} <button v-if="pending" :disabled="busy" @click="sendPending">Réessayer l’action</button></p><p v-if="notice" role="status">{{ notice }}</p>
   <CampaignEffects v-if="room.canManage" :campaign-id="id" :room="room" @changed="load" />
   <CampaignCombat v-if="room.combat?.active" ref="combatPanel" :campaign-id="id" :room="room" @changed="load" />
   <section class="active-sheet"><div class="sheet-heading"><h2>{{ chosen?.name??(room.canManage?'Choisis un participant':'Ta fiche en jeu') }}</h2><button v-if="room.ownCharacterId&&selected!==room.ownCharacterId" @click="selected=room.ownCharacterId">Revenir à mon personnage</button></div>
    <fieldset v-if="room.canManage&&chosen" class="participant-control" :disabled="busy"><legend>Place à la table · MJ</legend><div class="actor-controls"><label>Camp visible<select :value="chosen.side??'neutral'" @change="act('combat-participant',{actorId:chosen.id,version:room.combat.version,participating:chosen.participating!==false,side:($event.target as HTMLSelectElement).value})"><option value="ally">Allié</option><option value="enemy">Ennemi</option><option value="neutral">Neutre</option></select></label><button @click="act('combat-participant',{actorId:chosen.id,version:room.combat.version,participating:chosen.participating===false,side:chosen.side??'neutral'})">{{chosen.participating===false?'Réintégrer les tours':'Sortir des tours · fuite / retrait'}}</button></div><p>Le portrait et les PV sont conservés. Le retrait suspend les actions et la récupération de PA ; revenir conserve l’initiative et les PA restants.</p></fieldset>
    <details v-if="room.canManage&&chosen" class="gm-grace"><summary>Grâce du MJ · rétablir les PV</summary><form @submit.prevent="act('grace',{actorId:chosen.id,hp:graceHp,beforeHp:chosen.hp,reason:graceReason})"><p>Permet de sauver un personnage mort ou d’annuler des dégâts de test, sans dépenser d’Edge. L’initiative et les PA restent inchangés.</p><div class="actor-controls"><label>PV après la grâce<input v-model.number="graceHp" type="number" min="1" :max="chosen.pvMax" required /></label><button type="button" :disabled="busy" @click="graceHp=chosen.pvMax">Choisir le maximum · {{chosen.pvMax}} PV</button><label>Motif inscrit au journal partagé<input v-model="graceReason" maxlength="500" required /></label><button :disabled="busy||graceHp<1||graceHp>chosen.pvMax||!graceReason.trim()">Accorder la grâce à {{chosen.name}}</button></div></form></details>
    <CampaignCharacterPlay v-if="chosen?.kind==='character'&&(room.canManage||chosen.id===room.ownCharacterId)" :key="chosen.id" :character-id="chosen.id" :sheet-version="chosen.sheetVersion" :campaign-id="id" :combat-mode="!!room.combat?.active" @changed="load" />
    <template v-else-if="chosen&&room.canManage"><div v-if="room.combat?.active" class="combatant-status"><strong>{{ chosen.hp }} / {{ chosen.pvMax }} PV · {{ chosen.health }}</strong><span>{{ chosen.pa }} PA · Round {{ chosen.round }}</span><span>Initiative {{ chosen.initiative??'non lancée' }} · {{ chosen.paPerRound }} PA par round</span></div><section v-if="chosen.reference" class="participant-reference"><h3>Capacités, forces & faiblesses · MJ</h3><template v-for="group in [{key:'abilities',label:'Capacités'},{key:'strengths',label:'Forces'},{key:'weaknesses',label:'Faiblesses & limites'},{key:'equipment',label:'Équipement'},{key:'notes',label:'Notes de Vérité'}]" :key="group.key"><div v-if="chosen.reference[group.key]?.length"><h4>{{group.label}}</h4><p v-for="(text,i) in chosen.reference[group.key]" :key="i">{{text}}</p></div></template><div v-for="r in chosen.rolls.filter((r:any)=>r.id.startsWith('capability:'))" :key="r.id"><button @click="rollId=r.id;rollLabel=r.label">Préparer {{r.label}} · {{r.modifier}} + d10</button></div><details v-for="(s,i) in chosen.reference.ruleSections" :key="i"><summary>{{s.title}}</summary><p v-for="(line,j) in s.lines" :key="j">{{line}}</p></details></section><fieldset :disabled="busy" class="actor-roll"><legend>{{room.combat?.active?'Actions & jets du participant':'Jets courants du participant'}}</legend><form @submit.prevent="participantRoll"><div class="actor-controls"><label>Jet du participant<select v-model="rollId"><option v-for="r in availableRolls" :key="r.id" :value="r.id">{{ r.profile?r.profile+' · ':'' }}{{ r.label }} · {{ r.modifier }} + d10</option></select></label><label>Intitulé du jet<input v-model="rollLabel" maxlength="120" required /></label><label>Bonus / malus<input v-model.number="rollBonus" type="number" min="-100" max="100" required /></label><label>Stress minimum<select v-model.number="rollStress"><option :value="0">Neutre</option><option :value="1">Tendu</option><option :value="2">Paniqué</option></select></label><label v-if="room.combat?.active">PA à dépenser<input v-model.number="rollPa" type="number" min="0" max="20" required /></label><label class="check"><input v-model="rollPublic" type="checkbox" /> Publier le jet</label><button :disabled="!rollOption||!rollLabel.trim()">{{rollOption?.attack||rollOption?.requiresWeapon?'Choisir l’arme et la cible':'Lancer le d10 · participant'}}</button></div><p v-if="rollOption">{{ rollOption.modifier }} + bonus {{ rollBonus }} + d10 explosif<template v-if="rollOption.damage!==undefined"> · Dégâts de base {{ rollOption.damage }}</template></p><small>Le stress dû aux blessures s’applique automatiquement. Les jets d’un participant caché restent privés. Les PA indiqués sont déduits au lancer ; les dégâts sont appliqués après résolution de l’attaque.</small></form></fieldset><fieldset :disabled="busy"><legend>Suivi du participant</legend><div class="actor-controls"><label>Nom public<input v-model="actorName" maxlength="120" @input="actorDirty=true" /></label><label v-if="room.combat?.active">PA restants<input v-model.number="actorPa" type="number" min="0" max="20" @input="actorDirty=true" /></label><label class="check"><input type="checkbox" v-model="actorVisible" @change="actorDirty=true" /> Visible par les joueurs</label><button @click="actorAction('settings',{name:actorName,pa:actorPa,visible:actorVisible})">Enregistrer</button></div><div class="actor-controls"><label>Dégâts / soins<input v-model.number="amount" type="number" min="1" max="10000" /></label><button @click="actorAction('damage',{amount})">Subir les dégâts</button><button @click="actorAction('heal',{amount})">Recevoir les soins</button><button v-if="room.combat?.active&&chosen.participating!==false&&chosen.initiative===null" @click="actorAction('initiative')">Rejoindre le combat : initiative</button><button @click="actorAction('remove')">Retirer du combat</button></div></fieldset><details><summary>Fiche complète · MJ uniquement</summary><a v-if="chosen.sourceArticle" :href="`/compendium?article=${encodeURIComponent(chosen.sourceArticle)}`" target="_blank" rel="noopener">Ouvrir la fiche du Compendium ↗</a><CampaignNpcPreview v-else-if="chosen.kind==='npc'" :key="chosen.id" :campaign-id="id" :npc-id="chosen.sourceId" /><CampaignCreaturePreview v-else :key="chosen.id" :campaign-id="id" :creature-id="chosen.sourceId" /></details></template>
    <p v-else>{{ room.canManage?'Sélectionne un PJ pour consulter sa fiche, ou ajoute un participant depuis tes PNJ et ton bestiaire.':'Associe un personnage accepté à cette campagne pour retrouver sa fiche ici.' }}</p>
   </section>
  </main>
 </div></div>
</template>
